import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";
import * as ui from "@e2e/ui-actions";
import { MANTLE_BASE_URL } from "@e2e/config";

const WELCOME_SKILL = "Session Start";
const ACTIVE_SKILL = "Card Disambiguation";
const CARD_REPLACE_MESSAGE = "I need to replace my lost credit card";
const CARD_PICK_MESSAGE = "Summit Rewards 6338";

test.describe("Mantle skill mode", () => {
  test.use({
    // Skill-mode UI only exists on the Mantle agent (:5006) — `skill_state` is
    // emitted by the Mantle processor alone.
    baseURL: MANTLE_BASE_URL,
  });

  test("Skill document renders the active skill and memory groups under it with provenance", async ({
    inspectorPage,
  }) => {
    await flows.mantle.activateCardDisambiguationRouting(inspectorPage, {
      expectedWelcomeSkill: WELCOME_SKILL,
      replaceMessage: CARD_REPLACE_MESSAGE,
      recoveryPickMessage: CARD_PICK_MESSAGE,
    });

    await test.step("Assert the skill document renders the active ordered block", async () => {
      await ui.skillSection.assertions(inspectorPage).blockCanvasIsVisible();
      await ui.skillSection.assertions(inspectorPage).activeBlockIsExpanded();
      await ui.skillSection.assertions(inspectorPage).blockStepCountAtLeast(2);
    });

    await test.step("Switch to Memory view", async () => {
      await ui.viewMenu.actions(inspectorPage).switchToMemory();
      await ui.memoryPanel.assertions(inspectorPage).panelIsVisible();
    });

    await test.step("Assert the memory pane groups entries under the active skill", async () => {
      await ui.memoryPanel.assertions(inspectorPage).entryCountAtLeast(1);
      await ui.memoryPanel.assertions(inspectorPage).sectionIsVisible(ACTIVE_SKILL);
    });

    await test.step("Assert memory entries carry values and write provenance", async () => {
      await ui.memoryPanel.assertions(inspectorPage).entryHasValue(0);
      await ui.memoryPanel.assertions(inspectorPage).hasProvenanceBadge();
    });
  });
});
